(function(root){'use strict';function merge(current,incoming,{replace=false,readThrough,me}={}){let rows=new Map((replace?current.filter(m=>m.status==='sending'||m.status==='failed'):current).map(m=>[m.id,m]));for(let m of incoming){if(m.clientId)for(let [id,old]of rows)if(old.sender===m.sender&&old.clientId===m.clientId)rows.delete(id);rows.set(m.id,{...m,status:'sent'})}return[...rows.values()].map(m=>readThrough!==undefined&&m.sender===me&&m.status==='sent'?{...m,read:readThrough>=m.created}:m).sort((a,b)=>a.created-b.created||a.id.localeCompare(b.id))}const api={merge,threadId:(a,b)=>[a,b].sort().map(encodeURIComponent).join(':')};if(typeof module==='object')module.exports=api;else root.MuseMessageState=api})(globalThis);
